package main

import (
	"context"
	"fmt"
	"log"
	"strings"

	"github.com/jackc/pgx/v5"
)

func main() {
	rawData := `INSERT INTO houses_data (house_name, zodiac_sign, core_meaning, in_real_life, strengths, challenges, relationships, path_of_growth) VALUES
('House 7', 'Aries', 'Partnerships and marriage are approached with passion, independence, and a desire for action. You seek a partner who is a trailblazer.', 'You are drawn to dynamic, assertive individuals. Your relationships may develop quickly and often involve an element of competition or mutual pushing toward goals.', 'Courage in defending your partner, the ability to keep the spark alive through shared adventures, and an honest, direct approach to love.', 'Frequent arguments due to a clash of egos, impatience with your partner''s weaknesses, and a tendency to rush into commitments too quickly.', 'You need a relationship that feels exciting and alive. You despise complacency and prefer a partner who challenges you directly rather than being passive.', 'Learn the art of compromise. A partnership is not a competition; true strength in love comes from yielding just as much as leading.'),
('House 7', 'Taurus', 'Partnerships and marriage are built on stability, loyalty, and material security. You seek a partner who is dependable and sensually grounded.', 'You take your time before committing to someone. Once you do, you expect the relationship to last forever and provide a solid foundation of comfort and financial security.', 'Unwavering loyalty, the ability to build a deeply comfortable and secure life with a partner, and immense patience in resolving relationship issues.', 'Stubbornness during disagreements, staying in unhealthy relationships out of a fear of change, and a tendency toward possessiveness or jealousy.', 'You express love through physical affection and providing for your partner. You require a relationship that feels absolutely secure and predictable.', 'Embrace the fact that relationships must evolve to survive. Do not confuse emotional stagnation with stability.'),
('House 7', 'Gemini', 'Partnerships and marriage require constant communication, intellectual stimulation, and variety. You seek a partner who is, above all, a fascinating friend.', 'You are drawn to witty, intelligent, and talkative partners. Your ideal relationship involves constant dialogue, shared learning, and a lighthearted approach to life.', 'Exceptional communication skills within the partnership, the ability to keep the relationship youthful and fun, and a rational approach to solving relationship conflicts.', 'Fickleness, a fear of deep emotional enmeshment, intellectualizing relationship problems rather than feeling them, and easily becoming bored with your partner.', 'You need absolute freedom to socialize and communicate outside the relationship. Clinginess or silence will quickly drive you away.', 'Strive for emotional depth as well as intellectual connection. A true partnership requires sharing vulnerabilities, not just exchanging information.'),
('House 7', 'Cancer', 'Partnerships and marriage are deeply emotional, nurturing, and focused on creating a family. You seek a partner who offers absolute emotional safety.', 'You are drawn to sensitive, caring individuals. In relationships, you are highly protective and often take on a caregiving role, seeking a soul-deep connection.', 'Profound emotional intuition regarding your partner''s needs, unwavering devotion, and the ability to create a truly nurturing and safe domestic partnership.', 'Over-dependence on your partner, moodiness that creates instability in the relationship, and a tendency to become a "parent" rather than an equal partner.', 'You need to feel unconditionally loved and emotionally held by your partner. Any perceived threat to this security causes you to retreat into your shell.', 'Learn to establish emotional boundaries. Do not lose your individual identity in the partnership, and ensure that nurturing goes both ways.'),
('House 7', 'Leo', 'Partnerships and marriage are dramatic, warm, and built on mutual admiration. You seek a partner who is confident and can share the spotlight.', 'You treat romance like a grand performance. You want a partner whom you can be proud of, and you expect to be treated like royalty in return.', 'Immense generosity toward your partner, unwavering loyalty, a passionate and warm approach to love, and the ability to fiercely defend your relationship.', 'Dominating the partnership, a constant need for praise and validation from your partner, and allowing ego or pride to prevent necessary apologies.', 'You require a relationship filled with romance, grand gestures, and mutual respect. You despise petty squabbles and demand loyalty above all else.', 'Learn to share the stage. A truly regal partnership involves elevating your partner just as much as they elevate you.'),
('House 7', 'Virgo', 'Partnerships and marriage are built on practical support, service, and mutual improvement. You seek a partner who is competent, organized, and reliable.', 'You express your love by taking care of the practical details of your partner''s life. You are drawn to modest, hardworking individuals and prefer a quiet, orderly relationship.', 'Unwavering reliability, a genuine desire to help your partner succeed, excellent problem-solving skills within the relationship, and practical devotion.', 'Over-analyzing the relationship, being overly critical of your partner''s flaws, nagging, and struggling to relax and enjoy the romance.', 'You need a relationship that functions smoothly in daily life. You value competence over grand romantic gestures and despise laziness in a partner.', 'Learn to accept your partner''s imperfections. Do not treat your relationship as a project to be fixed. Cultivate unconditional acceptance.'),
('House 7', 'Libra', 'Partnerships and marriage are the absolute core of your existence. You seek an ideal, harmonious, and aesthetically pleasing relationship.', 'You are a natural romantic and may feel incomplete without a partner. You are drawn to charming, diplomatic individuals and strive to maintain total peace in the relationship.', 'Exceptional diplomacy and mediation skills, a deep dedication to fairness in the partnership, and the ability to create a beautifully romantic atmosphere.', 'Codependency, losing your own identity to please your partner, avoiding necessary conflicts which leads to built-up resentment, and indecisiveness.', 'You require absolute equality and harmony. You hate ugly confrontations and will often sacrifice your own needs just to keep the relationship stable.', 'Develop a strong sense of self independent of any partnership. Realize that healthy conflict is necessary to build a truly robust relationship.'),
('House 7', 'Scorpio', 'Partnerships and marriage are intense, transformative, and profoundly deep. You seek a soul-merging connection and absolute loyalty.', 'You are not interested in superficial relationships. You want to know your partner''s deepest secrets and are drawn to powerful, mysterious individuals. Your relationships often involve intense power dynamics.', 'Unwavering loyalty, incredible resilience in overcoming relationship crises, a deeply passionate connection, and the ability to heal your partner through intimacy.', 'Obsessive jealousy, possessiveness, a need to control the partnership, and a tendency to hold grudges or seek revenge if betrayed.', 'You demand total transparency and emotional depth from your partner. Trust is paramount; once broken, it is almost impossible to rebuild.', 'Learn to release control and trust your partner. True intimacy requires vulnerability, not dominance. Do not let paranoia destroy a good relationship.'),
('House 7', 'Sagittarius', 'Partnerships and marriage are viewed as grand adventures. You seek a partner who is philosophical, optimistic, and respects your freedom.', 'You are drawn to individuals from different cultures or backgrounds. You need a relationship that offers constant growth, travel, and intellectual exploration rather than domestic routine.', 'An optimistic and joyous approach to love, the ability to inspire your partner, and maintaining a healthy sense of independence within the relationship.', 'Fear of commitment, restlessness, overlooking the practical realities of a partnership, and a lack of tact that can unintentionally hurt your partner.', 'You require massive amounts of personal space and freedom. A clingy or overly domestic partner will make you feel trapped and eager to escape.', 'Learn that commitment does not equal imprisonment. Cultivate the discipline to stay present during the mundane, unadventurous parts of the relationship.'),
('House 7', 'Capricorn', 'Partnerships and marriage are serious, structured, and focused on long-term security. You seek a partner who is ambitious, mature, and respectable.', 'You do not rush into commitments. You view marriage almost as a business partnership, aiming to build a solid legacy and social status alongside your spouse.', 'Exceptional reliability, a steadfast commitment to the vows you make, providing immense material security, and acting as a rock for your partner.', 'Emotional coldness, treating the relationship like a transaction, a fear of vulnerability, and prioritizing work or status over romance.', 'You express love through duty and provision. You need a partner who understands the value of hard work and respects traditional relationship roles.', 'Allow yourself to be emotionally vulnerable with your partner. A successful marriage requires emotional warmth and romance just as much as financial security.'),
('House 7', 'Aquarius', 'Partnerships and marriage are unconventional, progressive, and built on deep friendship. You seek a partner who is unique, intellectual, and independent.', 'You are drawn to eccentric or brilliant individuals. Your ideal relationship defies traditional norms, often feeling more like a partnership of two independent best friends.', 'Tolerance, open-mindedness, a refusal to control or restrict your partner, and a highly intellectual approach to resolving relationship issues.', 'Emotional detachment, unpredictability, a fear of deep, messy emotional intimacy, and rebelling against commitment just to maintain your independence.', 'You require absolute intellectual freedom and personal space. You despise traditional, restrictive relationship roles and need a partner who is also your intellectual equal.', 'Learn to connect on a deep emotional level, not just an intellectual one. True intimacy requires showing your heart, not just your brilliant mind.'),
('House 7', 'Pisces', 'Partnerships and marriage are mystical, deeply empathetic, and boundless. You seek a spiritual soulmate and a transcendent romantic connection.', 'You are drawn to artistic, sensitive, or perhaps wounded individuals. You approach relationships with immense compassion and a desire to merge completely on a spiritual level.', 'Profound empathy for your partner, supreme romantic devotion, unconditional love, and the ability to heal your partner through your deep understanding.', 'Lacking boundaries, falling into the savior/victim dynamic, idealizing your partner while ignoring red flags, and losing yourself completely in the relationship.', 'You require a deeply soulful and romantic connection. You are highly adaptable to your partner''s needs but must be careful not to be taken advantage of.', 'Ground your romantic ideals in reality. Establish firm personal boundaries and learn to see your partner as a flawed human being rather than an idealized fantasy.'),
('House 8', 'Aries', 'Transformation, shared resources, and intimacy are approached with courage, directness, and a pioneering spirit. You confront psychological crises head-on.', 'You are fearless when facing life''s darker themes, such as death, taxes, or deep psychological trauma. In intimate relationships, you are passionate and demand direct honesty.', 'Exceptional bravery during times of crisis, the ability to quickly cut ties with toxic situations, and a fearless approach to profound personal transformation.', 'Impulsiveness in handling joint finances, a tendency to argue aggressively over inheritances or shared resources, and a lack of patience for subtle psychological work.', 'You demand independence even in the most intimate, merged situations. You may struggle with the vulnerability required for true emotional merging, preferring to remain the "strong one."', 'Learn that true transformation sometimes requires patience and surrendering control. Do not treat intimacy as a battle to be won.'),
('House 8', 'Taurus', 'Transformation and intimacy are rooted in stability, sensuality, and material security. You seek profound comfort and permanence in deep emotional bonds.', 'You are cautious about sharing resources or merging intimately. Once you do, you expect the bond to be unbreakable. You may gain financially through partnerships or inheritances.', 'Incredible endurance during psychological crises, a talent for managing and growing joint finances, and a deeply grounded, sensual approach to intimacy.', 'Extreme stubbornness when faced with necessary transformation, hoarding shared resources out of fear, and intense possessiveness or jealousy in intimate relationships.', 'You require absolute material and emotional security before you will truly merge with someone. You express deep intimacy through physical touch and provision.', 'Learn to let go. True transformation requires releasing your grip on what you think makes you secure. Embrace the inevitable changes of life.'),
('House 8', 'Gemini', 'Transformation, shared resources, and intimacy are intellectualized and explored through communication. You seek a psychological connection that is, above all, mentally stimulating.', 'You are curious about the mysteries of life, death, and psychology, often reading or talking extensively about these subjects. You prefer to discuss intimacy rather than dive blindly into the emotional depths.', 'The ability to rationalize and communicate clearly during a crisis, a versatile approach to managing joint finances, and a brilliant, curious psychological mind.', 'Superficiality when dealing with profound emotional trauma, a tendency to gossip about others'' secrets, and an inability to sit with silent, deep emotions.', 'You need to talk through everything in an intimate relationship. If a partner refuses to communicate their deepest thoughts, you will quickly lose interest.', 'Learn to feel your emotions without needing to explain or rationalize them immediately. Some transformations happen in silence, beyond words.'),
('House 8', 'Cancer', 'Transformation and intimacy are profoundly emotional, intuitive, and tied to a need for absolute soul-level security. You merge with others through deep nurturing.', 'You are highly sensitive to the psychological currents around you. You are fiercely protective of your shared resources and require immense emotional trust before allowing anyone into your inner sanctum.', 'Profound psychological intuition, the ability to heal the deep emotional wounds of others, and an incredible capacity for soulful, nurturing intimacy.', 'Clinging desperately to past traumas, a fear of letting go of toxic relationships due to emotional attachment, and using guilt to manipulate intimate partners.', 'You seek a bond that feels like a return to the womb—safe, warm, and completely unified. Any breach of trust in this area is deeply devastating to you.', 'Learn to release past hurts and forgive. Do not let your fear of abandonment prevent you from undergoing necessary personal transformations.'),
('House 8', 'Leo', 'Transformation, shared resources, and intimacy are dramatic, passionate, and tied to pride. You want to shine even in the darkest and most hidden areas of life.', 'You approach joint finances and intimate relationships with generosity and a desire for control. You may gain wealth through a partner but expect to be recognized for your contribution to the shared pot.', 'Immense courage and dignity during times of crisis, a deeply passionate and warm approach to intimacy, and the ability to bring light to dark psychological spaces.', 'Arrogance regarding joint resources, a refusal to admit vulnerability or weakness, and a tendency to turn intimate conflicts into dramatic ego clashes.', 'You demand fierce loyalty and adoration in your most intimate bonds. You want to be proud of the person you merge with and expect them to treat you as their ultimate treasure.', 'Learn to put your pride aside. True intimacy requires admitting your flaws and vulnerabilities without fearing that you will lose your dignity.'),
('House 8', 'Virgo', 'Transformation, shared resources, and intimacy are approached analytically, practically, and with a desire to "fix" or improve. You dissect the mysteries of life.', 'You are meticulous in managing joint finances, taxes, and inheritances. In intimate relationships, you analyze the psychological dynamics carefully and seek to improve the bond through practical service.', 'Exceptional skill in untangling complex financial or psychological messes, a humble and dedicated approach to deep intimacy, and profound analytical insight.', 'Over-analyzing emotional trauma, criticizing your partner during intimate moments, a fear of losing control by surrendering to passion, and worrying excessively about shared finances.', 'You show deep trust by offering practical help and organizing your partner''s life. You struggle with the messy, irrational nature of deep emotional merging.', 'Learn to turn off your analytical mind. True intimacy and profound transformation are often chaotic and cannot be neatly organized or perfected.'),
('House 8', 'Libra', 'Transformation and intimacy are centered around balance, aesthetics, and achieving perfect harmony with another. You seek a beautiful, refined merging of souls.', 'You are highly diplomatic when dealing with shared resources and strive for absolute fairness in joint finances. You desire an intimate relationship that is both profound and peaceful.', 'Excellent mediation skills during crises, the ability to create harmony in deeply intimate spaces, and a refined, romantic approach to profound psychological bonding.', 'Avoiding necessary deep psychological confrontations to keep the peace, indecisiveness regarding joint finances, and codependency in intimate relationships.', 'You view deep intimacy as the ultimate partnership. You loathe ugly emotional outbursts and may suppress your own dark feelings to maintain a beautiful facade.', 'Do not be afraid of the "ugly" side of human nature. True transformation requires facing the darkness, and true intimacy requires absolute honesty, even when it is not peaceful.'),
('House 8', 'Scorpio', 'Transformation, shared resources, and intimacy are the absolute core of this placement. You dive fearlessly into the darkest, most intense areas of the human experience.', 'This is the natural home of Scorpio. You possess profound psychological depth, a fascination with the occult or the mysteries of death, and a demand for absolute, soul-consuming intimacy.', 'Unmatched psychological resilience, the ability to regenerate completely after a crisis, profound insight into the motives of others, and intense, transformative passion.', 'Paranoia, an obsessive need for control in intimate relationships, holding onto deep-seated resentments, and a tendency toward destructive power struggles.', 'You demand total transparency, absolute loyalty, and complete emotional merging. You are fiercely protective of your shared resources and intimate secrets.', 'Learn to forgive and let go. Your immense power must be used for healing, not for control or revenge. Trust that vulnerability is your greatest strength.'),
('House 8', 'Sagittarius', 'Transformation and intimacy are approached with optimism, a philosophical mindset, and a desire for expansion. You seek meaning in life''s darkest moments.', 'You are not afraid of crises because you view them as opportunities for growth and learning. You are generous with shared resources and approach intimacy as an adventurous exploration.', 'Profound philosophical understanding of life and death, the ability to maintain optimism during a crisis, and a joyful, expansive approach to deep intimacy.', 'Recklessness with joint finances, overlooking the subtle psychological nuances of a partner, and a tendency to philosophize pain rather than actually feeling it.', 'You require freedom even in the most intimate bonds. If an intimate relationship feels restrictive or heavy, you will seek a way to escape or expand your horizons.', 'Learn to sit with the heavy, uncomfortable emotions. Not every crisis can be immediately rationalized into a positive philosophical lesson. Respect your partner''s need for deep emotional processing.'),
('House 8', 'Capricorn', 'Transformation, shared resources, and intimacy are structured, disciplined, and approached with extreme caution. You take the profound matters of life very seriously.', 'You are highly responsible with joint finances, taxes, and inheritances. You do not merge intimately easily, requiring a long time to build the necessary trust and structure for a deep bond.', 'Exceptional reliability in managing shared assets, a stoic resilience during crises, and a deep, enduring commitment once you finally choose to merge with someone.', 'Emotional coldness in intimate spaces, a fear of vulnerability that prevents true merging, treating joint resources purely as a business transaction, and deep-seated pessimism.', 'You express deep intimacy by taking on responsibility for your partner. You need a structured, predictable environment to feel safe enough to reveal your hidden depths.', 'Allow yourself to surrender control. Intimacy is not a business contract; it requires emotional warmth and the courage to be completely vulnerable without a safety net.'),
('House 8', 'Aquarius', 'Transformation and intimacy are unconventional, intellectualized, and highly objective. You seek a progressive, independent approach to deep emotional bonding.', 'You are fascinated by psychology but approach it scientifically rather than emotionally. You prefer unconventional arrangements for shared resources and require immense personal space in intimate relationships.', 'Brilliant, objective insight into human psychology, the ability to detach and remain calm during a crisis, and an open-minded, tolerant approach to intimacy.', 'Extreme emotional detachment that frustrates intimate partners, rebelling against deep commitment, and an inability to handle the messy, irrational nature of human trauma.', 'You view intimate partners as friends and equals. You despise possessiveness or jealousy and demand that your individual freedom be respected, even when deeply merged.', 'Learn to connect with the raw, irrational emotions of the heart. Intellectualizing trauma or intimacy prevents true, profound psychological transformation.'),
('House 8', 'Pisces', 'Transformation, shared resources, and intimacy are fluid, spiritual, and boundless. You seek a mystical, transcendent merging of souls.', 'You are incredibly sensitive to the psychological energies around you. You approach joint finances with a fluid, generous attitude and seek an intimate bond that transcends the physical realm.', 'Profound spiritual insight into life and death, immense compassion for the trauma of others, and the ability to heal deeply through unconditional love and mystical intimacy.', 'A lack of boundaries that leads to being taken advantage of financially or emotionally, getting lost in illusions, and taking on the psychological burdens of others.', 'You seek absolute spiritual fusion. You are highly adaptable in intimate settings but must guard against toxic individuals who may drain your immense energetic resources.', 'Establish iron-clad boundaries regarding your shared resources and your emotional energy. Learn to protect yourself so that your profound compassion is not exploited.'),
('House 9', 'Aries', 'Philosophy, higher learning, and travel are approached with fiery enthusiasm, independence, and a pioneering spirit. You are a crusader for your beliefs.', 'You love to travel spontaneously and seek out adventurous, active experiences abroad. Your belief system is strong, and you will fiercely defend your philosophical or religious views.', 'Courage to explore the unknown, an inspiring and energetic approach to teaching or learning, and the ability to initiate grand, visionary projects.', 'Dogmatism, a tendency to argue aggressively over beliefs, impulsiveness in travel plans, and lacking the patience for long, structured academic studies.', 'You are an independent thinker who dislikes being told what to believe. You inspire others with your bold visions but can be impatient with those who learn slower than you.', 'Cultivate patience and respect for differing viewpoints. Learn that true wisdom often involves listening to others, not just conquering debates.'),
('House 9', 'Taurus', 'Philosophy, higher learning, and travel are grounded, practical, and focused on tangible results. You seek absolute stability in your belief systems.', 'You prefer to travel in comfort and enjoy experiencing the physical beauty and food of different cultures. You learn best through practical application and hold fast to traditional or proven philosophies.', 'Steadfast dedication to higher learning, the ability to build practical structures based on grand philosophies, and a deeply grounded, sensual appreciation of the world.', 'Extreme stubbornness regarding your beliefs, a refusal to explore abstract concepts that lack tangible proof, and a reluctance to travel outside your comfort zone.', 'You build your life philosophy slowly and rarely change it. You provide a stabilizing influence for others, showing them how to ground their grand ideas in reality.', 'Open your mind to the abstract and the unknown. Understand that just because something cannot be touched does not mean it lacks profound value.'),
('House 9', 'Gemini', 'Philosophy, higher learning, and travel are characterized by curiosity, variety, and constant intellectual stimulation. You are an eternal student of the world.', 'You love to gather information from diverse cultures, religions, and philosophies. You prefer short, frequent trips to long, arduous journeys and enjoy discussing your findings with everyone.', 'Exceptional versatility in learning, a brilliant and inquisitive mind, the ability to communicate complex philosophies clearly, and a tolerant, open-minded worldview.', 'Superficial understanding of complex subjects, a short attention span that prevents deep academic mastery, and changing your beliefs too frequently based on the latest trend.', 'You thrive in academic or travel environments that offer constant conversation and new data. You are a fascinating teacher who keeps students constantly engaged.', 'Learn to focus your mind and dive deeply into a single subject. Breadth of knowledge is wonderful, but depth of understanding is necessary for true wisdom.'),
('House 9', 'Cancer', 'Philosophy, higher learning, and travel are deeply emotional, intuitive, and tied to a search for emotional security. You seek a belief system that feels like "home."', 'You are drawn to studying history, ancestry, or psychology. When you travel, you seek places that offer emotional comfort or remind you of your roots. Your beliefs are deeply tied to your family''s traditions.', 'Profound emotional understanding of different cultures, the ability to teach with immense empathy, and a strong intuitive grasp of complex philosophical concepts.', 'Allowing emotions to cloud objective philosophical inquiry, clinging rigidly to the beliefs of your parents out of nostalgia, and xenophobia or a fear of the unfamiliar.', 'You need to feel emotionally connected to what you are studying or where you are traveling. You are a nurturing teacher who cares deeply for your students'' well-being.', 'Learn to separate your emotional attachments from objective truth. Be willing to explore philosophies that challenge your comfortable worldview.'),
('House 9', 'Leo', 'Philosophy, higher learning, and travel are dramatic, warm, and tied to pride. You seek a grand, inspiring worldview that allows you to shine as a leader or teacher.', 'You love to travel in style and experience the grandeur of the world. You hold your beliefs with passionate conviction and love to share your wisdom with an audience.', 'Charismatic teaching abilities, a generous and inspiring worldview, immense creative vision, and the courage to stand proudly by your philosophical convictions.', 'Intellectual arrogance, dogmatism, a need to be admired for your intellect, and a refusal to admit when your beliefs are wrong.', 'You expect respect for your intellect and worldview. You are a natural leader in academic or religious settings, capable of inspiring large groups of people.', 'Learn the virtue of intellectual humility. True wisdom requires recognizing how much you do not know and being willing to learn from those you consider your subordinates.'),
('House 9', 'Virgo', 'Philosophy, higher learning, and travel are analytical, practical, and focused on detailed mastery. You seek a belief system that is logical and useful for serving others.', 'You excel in academic environments due to your meticulous attention to detail. You prefer purposeful travel, such as work trips or educational tours, rather than idle vacations.', 'Exceptional research skills, a brilliant analytical mind, the ability to organize complex philosophical systems, and a humble dedication to higher learning.', 'Getting lost in minor academic details while missing the big picture, over-analyzing belief systems until they lose their meaning, and extreme criticism of differing views.', 'You approach the search for meaning as a puzzle to be solved. You are a highly effective, though demanding, teacher who insists on accuracy and practical application.', 'Learn to step back and look at the forest, not just the trees. Allow yourself to experience the awe and mystery of the world without needing to categorize it immediately.'),
('House 9', 'Libra', 'Philosophy, higher learning, and travel are centered around harmony, aesthetics, and social justice. You seek a belief system that promotes balance and fairness.', 'You are drawn to studying law, art, or sociology. You prefer traveling with a partner and seek out culturally refined, beautiful destinations. Your worldview is built on diplomacy.', 'A deeply fair and objective worldview, the ability to see multiple sides of a philosophical debate, and a talent for promoting peace and cultural understanding.', 'Indecisiveness regarding your own core beliefs, adopting the philosophies of your partner to avoid conflict, and a tendency to prioritize aesthetics over hard truths.', 'You thrive in academic or travel settings where you can collaborate. You are an excellent mediator who uses your higher knowledge to bring people together.', 'Do not be afraid to take a firm stand on a philosophical issue, even if it causes conflict. True justice sometimes requires disrupting the peace.'),
('House 9', 'Scorpio', 'Philosophy, higher learning, and travel are intense, transformative, and deeply psychological. You seek absolute, unvarnished truth, no matter how dark.', 'You are fascinated by the occult, psychology, or the mysteries of life and death. You prefer travel that completely transforms you, perhaps visiting intense or historically significant locations.', 'Profound insight into the hidden truths of the universe, unwavering focus in academic research, and the ability to completely regenerate your worldview after a crisis.', 'Dogmatic obsession with your beliefs, paranoia regarding foreign cultures or differing philosophies, and using your knowledge to manipulate or control others.', 'You are a formidable student and teacher, demanding absolute depth and honesty. You despise superficial philosophies and will relentlessly question accepted dogmas.', 'Use your penetrating insight to heal and transform, not to destroy. Learn to trust that the universe is not always a dark, secretive place; there is light to be found as well.'),
('House 9', 'Sagittarius', 'Philosophy, higher learning, and travel are the absolute core of your existence. You are the ultimate explorer, seeking boundless expansion and ultimate truth.', 'This is the natural home of Sagittarius. You are a lifelong student of the world, possessing an insatiable wanderlust and a deep need to understand different cultures, religions, and grand concepts.', 'Visionary optimism, a profoundly inspiring worldview, a natural talent for teaching and publishing, and a joyous, expansive approach to life''s grand journey.', 'Recklessness, a tendency to preach rather than listen, overlooking crucial details in favor of grand theories, and a restless inability to stay in one place or philosophy.', 'You inspire others with your massive vision and boundless enthusiasm. You must have the freedom to roam intellectually and physically to feel truly alive.', 'Cultivate discipline and attention to detail. A grand vision requires a solid foundation to be realized. Learn to ground your soaring philosophies in practical reality.'),
('House 9', 'Capricorn', 'Philosophy, higher learning, and travel are structured, ambitious, and focused on achieving authority. You seek a belief system that provides tangible success and respect.', 'You take your education very seriously, often viewing it as a stepping stone to career advancement. You prefer organized, purposeful travel and hold conservative or highly pragmatic beliefs.', 'Exceptional academic discipline, the ability to master complex subjects through hard work, strategic long-term planning, and a deep respect for traditional wisdom.', 'Pessimism, mental rigidity, dismissing abstract or spiritual philosophies as useless, and treating higher learning purely as a business transaction.', 'You are an authoritative figure in your chosen field of study. You respect established institutions and prefer to build your worldview on solid, proven facts rather than theories.', 'Open your mind to the abstract and the spiritual. Understand that not all valuable knowledge results in immediate material success or social status.'),
('House 9', 'Aquarius', 'Philosophy, higher learning, and travel are unconventional, progressive, and focused on humanitarian ideals. You seek a worldview that breaks the rules and advances society.', 'You are drawn to studying science, technology, or progressive sociology. You prefer traveling off the beaten path and hold highly original, sometimes eccentric, philosophical views.', 'Brilliant originality in thought, a deeply objective and tolerant worldview, the ability to grasp futuristic concepts, and a dedication to collective human progress.', 'Intellectual superiority, extreme stubbornness regarding your unique views, rebelling against traditional education just to be contrary, and emotional detachment from your beliefs.', 'You view the world as a global community. You are a fascinating, forward-thinking teacher who encourages students to question everything and think outside the box.', 'Learn to integrate emotional intelligence into your brilliant worldview. Remember that humanity is driven by the heart just as much as by the mind.'),
('House 9', 'Pisces', 'Philosophy, higher learning, and travel are mystical, fluid, and deeply intuitive. You seek a spiritual truth that transcends logic and boundaries.', 'You are drawn to studying mysticism, art, or healing. You prefer travel that feels like a spiritual pilgrimage or an escape from reality. Your beliefs are rooted in universal compassion.', 'Profound spiritual insight, an incredible imagination that grasps abstract concepts effortlessly, boundless empathy for different cultures, and visionary inspiration.', 'Mental confusion, a lack of focus in academic settings, getting lost in illusions or cult-like philosophies, and struggling to articulate your profound visions logically.', 'You absorb knowledge osmotically rather than through rigid study. You are a deeply compassionate teacher who seeks to uplift the souls of your students.', 'Ground your mystical visions in logical structure. Develop the discipline to study effectively and learn to clearly articulate your spiritual insights so others can benefit from them.');`

	valuesStr := strings.TrimPrefix(rawData, "INSERT INTO houses_data (house_name, zodiac_sign, core_meaning, in_real_life, strengths, challenges, relationships, path_of_growth) VALUES\n")
	valuesStr = strings.TrimSpace(valuesStr)
	valuesStr = strings.TrimSuffix(valuesStr, ";")

	ctx := context.Background()
	conn, err := pgx.Connect(ctx, "postgres://zodiac_user:zodiac_pass@localhost:5432/zodiac_db?sslmode=disable")
	if err != nil {
		log.Fatalf("Unable to connect to database: %v\n", err)
	}
	defer conn.Close(ctx)

	insertQuery := fmt.Sprintf(`
		WITH data(house_name, zodiac_sign, core_meaning, real_life, strengths, challenges, relationships, growth_path) AS (
			VALUES %s
		)
		INSERT INTO placement_interpretations (
			language, factor_type, factor_value_1, factor_value_3, factor_value_2,
			core_meaning, real_life, strengths, challenges, relationships, growth_path
		)
		SELECT 
			'en', 
			'house_in_sign', 
			trim(replace(house_name, 'House', '')), 
			'', 
			zodiac_sign,
			core_meaning, real_life, strengths, challenges, relationships, growth_path
		FROM data
		ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3)
		DO UPDATE SET
			core_meaning = EXCLUDED.core_meaning,
			real_life = EXCLUDED.real_life,
			strengths = EXCLUDED.strengths,
			challenges = EXCLUDED.challenges,
			relationships = EXCLUDED.relationships,
			growth_path = EXCLUDED.growth_path,
			updated_at = CURRENT_TIMESTAMP;
	`, valuesStr)

	tag, err := conn.Exec(ctx, insertQuery)
	if err != nil {
		log.Fatalf("Insert failed: %v", err)
	}

	fmt.Printf("Successfully inserted/updated House 7-9 data! Rows affected: %d\n", tag.RowsAffected())
}
